module.exports.config = {
    name: "banthread",
    version: "1.0", 
    hasPermssion: 2,
    credits: "cc",
    description: "ban hoặc gỡ ban nhóm sử dụng bot",
    commandCategory: "Hệ thống",
    usages: [
        "banthread [lý do]: ban nhóm hiện tại.",
        "banthread unban: Gỡ ban nhóm hiện tại.",
        "banthread <ID nhóm> [lý do]: ban/gỡ ban nhóm bằng ID.",
        "banthread list: Xem danh sách các nhóm bị ban."
    ],
    cooldowns: 5,
    dependencies: {
        "moment-timezone": ""
    }
};

module.exports.run = async function({ api, event, args, Threads }) {
    const { threadID, messageID } = event;
    const moment = require("moment-timezone");

    const [action, ...reasonArr] = args;
    let reason = reasonArr.join(" ") || "Không có lý do.";

    if (action === "list") {
        const bannedThreads = Object.keys(global.data.threadBanned);
        if (bannedThreads.length === 0) {
            return api.sendMessage("✅ Hiện tại không có nhóm nào bị ban.", threadID, messageID);
        }

        let msg = "--- DANH SÁCH NHÓM BỊ ban ---\n\n";
        let count = 1;

        for (const bannedID of bannedThreads) {
            const info = global.data.threadBanned[bannedID];
            try {
                const threadInfo = await Threads.getInfo(bannedID);
                const name = threadInfo.threadName || "Không thể lấy tên";
                const formattedDate = moment(info.dateAdded).tz("Asia/Ho_Chi_Minh").format("HH:mm:ss DD/MM/YYYY");
                msg += `${count}. Tên nhóm: ${name}\n   - ID: ${bannedID}\n   - Lý do: ${info.reason}\n   - Ngày ban: ${formattedDate}\n\n`;
                count++;
            } catch (e) {
                msg += `${count}. ID: ${bannedID} (Bot không còn trong nhóm này)\n   - Lý do: ${info.reason}\n\n`;
                count++;
            }
        }
        return api.sendMessage(msg, threadID, messageID);
    }

    let targetID = action;

    if (action === "unban") {
        targetID = threadID;
        if (!global.data.threadBanned.hasOwnProperty(targetID)) {
            return api.sendMessage("ℹ️ Nhóm này không nằm trong danh sách bị ban.", threadID, messageID);
        }
        delete global.data.threadBanned[targetID];
        return api.sendMessage("✅ Đã gỡ ban thành công cho nhóm này.", threadID, messageID);
    }

    if (isNaN(parseInt(action))) {
        targetID = threadID;
        reason = args.join(" ") || "Không có lý do.";
    }

    try {
        const threadInfo = await Threads.getInfo(targetID);
        const threadName = threadInfo.threadName || "nhóm này";
        if (global.data.threadBanned.hasOwnProperty(targetID)) {
            delete global.data.threadBanned[targetID];
            api.sendMessage(`✅ Đã gỡ ban cho nhóm '${threadName}' (ID: ${targetID}).`, threadID, messageID);
        } else {
            global.data.threadBanned[targetID] = {
                reason: reason,
                dateAdded: new Date().toISOString()
            };
            api.sendMessage(` Đã ban nhóm '${threadName}' (ID: ${targetID}) với lý do: ${reason}.`, threadID, messageID);
        }
};

